<?php
require_once __DIR__.'/../services/KMeans.php';$data=student_matrix($pdo);$valid=array_values(array_filter($data,fn($r)=>!in_array(null,$r['values'],true)));$evaluations=[];$error='';
if(count($valid)>=6){$raw=array_map(fn($r)=>$r['values'],$valid);for($k=2;$k<=min(6,count($valid)-1);$k++){try{$r=KMeans::fit($raw,$k,100,0.0001,42);$evaluations[]=['k'=>$k,'sse'=>$r['sse'],'silhouette'=>$r['silhouette'],'iterations'=>$r['iterations'],'status'=>'Berhasil'];}catch(Throwable $e){$evaluations[]=['k'=>$k,'sse'=>null,'silhouette'=>null,'iterations'=>0,'status'=>'Gagal'];}}}else{$error='Data nilai lengkap belum cukup untuk evaluasi K=2 sampai K=6.';}
$latest=latest_run($pdo);
?>
<div class="page-heading"><div><div class="eyebrow">VALIDASI MODEL</div><h1>Evaluasi Model</h1><p>Bandingkan SSE, pola Elbow, dan Silhouette untuk beberapa nilai K.</p></div></div>
<div class="notice"><strong>Evaluasi dihitung saat halaman dibuka</strong><span>Model uji memakai data nilai lengkap yang tersedia dan standardisasi Z-score. Seed evaluasi = 42.</span></div>
<?php if($error): ?><div class="alert alert-warning"><?= e($error) ?></div><?php else: ?><div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Elbow Method</h2><p>Hubungan jumlah cluster dan SSE</p></div></div><div class="chart-wrap"><canvas id="elbowChart"></canvas></div><script type="application/json" id="elbowData"><?= json_encode(['labels'=>array_column($evaluations,'k'),'values'=>array_map(fn($x)=>round($x['sse'],4),$evaluations)]) ?></script><p class="small muted">SSE cenderung menurun ketika K bertambah. Pilih elbow berdasarkan perubahan laju penurunan, bukan hanya SSE terendah.</p></section><section class="panel"><div class="panel-heading"><div><h2>Silhouette Coefficient</h2><p>Ukuran kohesi dan pemisahan cluster</p></div></div><div class="chart-wrap"><canvas id="silhouetteChart"></canvas></div><script type="application/json" id="silhouetteData"><?= json_encode(['labels'=>array_column($evaluations,'k'),'values'=>array_map(fn($x)=>$x['silhouette']===null?null:round($x['silhouette'],4),$evaluations)]) ?></script><p class="small muted">Nilai berada pada rentang -1 sampai 1. Nilai lebih tinggi umumnya menunjukkan pemisahan lebih baik.</p></section></div>
<section class="panel mt-24"><div class="panel-heading"><div><h2>Tabel perbandingan model</h2><p><?= count($valid) ?> mahasiswa lengkap diuji pada setiap nilai K.</p></div></div><div class="table-scroll"><table><thead><tr><th>K</th><th>SSE</th><th>Silhouette</th><th>Iterasi</th><th>Status</th></tr></thead><tbody><?php foreach($evaluations as $r): ?><tr><td><strong>K = <?= $r['k'] ?></strong></td><td><?= fmt($r['sse'],4) ?></td><td><?= $r['silhouette']===null?'—':fmt($r['silhouette'],4) ?></td><td><?= (int)$r['iterations'] ?></td><td><span class="pill pill-success"><?= e($r['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="panel mt-24"><div class="panel-heading"><div><h2>Catatan interpretasi</h2><p>Gunakan metrik bersama konteks penelitian.</p></div></div><ul class="plain-list"><li><strong>SSE:</strong> jumlah kuadrat jarak titik terhadap centroid cluster masing-masing pada data terstandardisasi. Angka lebih rendah tidak otomatis berarti model terbaik karena SSE umumnya turun saat K meningkat.</li><li><strong>Elbow:</strong> cari titik ketika penambahan cluster tidak lagi menurunkan SSE secara signifikan. Interpretasi dapat bersifat subjektif.</li><li><strong>Silhouette:</strong> mempertimbangkan kedekatan data terhadap cluster sendiri dibandingkan cluster alternatif terdekat.</li><li><strong>Keputusan K:</strong> pertimbangkan SSE, Silhouette, interpretabilitas, dan kebutuhan penelitian. Jangan memaksakan K=3 jika hasil evaluasi tidak mendukung.</li></ul><?php if($latest): ?><p class="small muted">Proses terakhir tersimpan menggunakan K=<?= (int)$latest['jumlah_cluster'] ?> dengan SSE <?= fmt((float)$latest['sse'],3) ?> dan Silhouette <?= $latest['silhouette']===null?'tidak tersedia':fmt((float)$latest['silhouette'],3) ?>.</p><?php endif; ?></section>
